using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
[InitializeOnLoad] public static class MergeSceneAudit {
 static readonly List<string> playErrors=new List<string>();
 static MergeSceneAudit(){if(SessionState.GetBool("MergeSceneAudit.Play",false)){EditorApplication.update+=CheckPlay;Application.logMessageReceived+=CaptureError;}}
 static void CaptureError(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)playErrors.Add(message);}
 public static void RunPlay(){EditorSceneManager.OpenScene("Assets/Scenes/bongyuri.unity");SessionState.SetBool("MergeSceneAudit.Play",true);EditorApplication.update+=CheckPlay;Application.logMessageReceived+=CaptureError;EditorApplication.isPlaying=true;}
 static void CheckPlay(){if(!EditorApplication.isPlaying||Time.time<2.5f)return;EditorApplication.update-=CheckPlay;SessionState.SetBool("MergeSceneAudit.Play",false);try{
 var nav=UnityEngine.Object.FindFirstObjectByType<FirstConveyorViewSwitch>();if(nav==null)throw new Exception("Navigation absent in Play");var report=new List<string>();
 foreach(string terminal in new[]{"A","B","C"}){if(terminal=="A"){nav.ShowContainerA();nav.ShowContainerAArm();}else if(terminal=="B"){nav.ShowContainerB();nav.ShowContainerBArm();}else{nav.ShowContainerC();nav.ShowContainerCArm();}var cam=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsInactive.Include).Single(c=>c.name=="Camera"+terminal+"_Arm");if(!cam.enabled||cam.targetDisplay!=4)throw new Exception("Camera not selected/output display wrong: "+terminal);nav.GoBack();var back=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsInactive.Include).Single(c=>c.name=="CameraContainer"+terminal);if(!back.enabled)throw new Exception("Back camera wrong: "+terminal);report.Add(terminal+" arm camera and Back OK");}
 nav.ShowFirst();if(playErrors.Count>0)throw new Exception(string.Join("\n",playErrors));File.WriteAllLines("Logs/MergePlayAudit.txt",new[]{"PASS Play startup and camera navigation; robot motion not exercised"}.Concat(report));EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText("Logs/MergePlayAudit.txt","FAIL\n"+e);EditorApplication.Exit(1);}}
 public static void Run(){
 var lines=new List<string>();Directory.CreateDirectory("Logs");try{
 var scene=EditorSceneManager.OpenScene("Assets/Scenes/bongyuri.unity");
 var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MonoBehaviour>(true)).Where(x=>x!=null).ToArray();
 foreach(var pair in new[]{("SuctionStation_02",new Vector3(.4999981f,0,-3.9700003f)),("SuctionStation_03",new Vector3(.20999908f,0,-7.88f))}) {var group=GameObject.Find(pair.Item1);if(group==null)throw new Exception("Preserved robot group missing");if(group.transform.parent!=null||Vector3.Distance(group.transform.position,pair.Item2)>.001f||(group.transform.lossyScale-Vector3.one).sqrMagnitude>.00001f)throw new Exception("Preserved robot group placement changed: "+pair.Item1);} var cell=all.OfType<CellController>().Single();lines.Add("CellController: one");
 var nav=all.OfType<FirstConveyorViewSwitch>().Single();var navSO=new SerializedObject(nav);
 foreach(string name in new[]{"firstCamera","topCamera","containerACamera","containerBCamera","containerCCamera","containerAArmCamera","containerBArmCamera","containerCArmCamera","containerAArmButton","containerBArmButton","containerCArmButton"}) {if(navSO.FindProperty(name).objectReferenceValue==null)throw new Exception("Missing camera/UI reference: "+name);lines.Add(name+": connected");}
 foreach(var panel in all.Where(x=>x is DashboardUI||x is CellOperatorUI||x.GetType().Name=="BoxInfoPanel")){var so=new SerializedObject(panel);var p=so.FindProperty("controller");if(p!=null){p.objectReferenceValue=cell;so.ApplyModifiedPropertiesWithoutUndo();}if(panel is BoxInfoPanel){so.FindProperty("correctionLine").objectReferenceValue=new SerializedObject(cell).FindProperty("correctLine").objectReferenceValue;so.ApplyModifiedPropertiesWithoutUndo();}lines.Add(panel.GetType().Name+": linked to CellController");}
 foreach(var correction in all.OfType<CorrectionSequence>()){
 var ik=correction.GetComponent<FrontArmIK>();if(ik==null)throw new Exception("FrontArmIK missing");var cs=new SerializedObject(correction);cs.FindProperty("ik").objectReferenceValue=ik;cs.ApplyModifiedPropertiesWithoutUndo();var iks=new SerializedObject(ik);if(iks.FindProperty("tcp").objectReferenceValue==null){iks.FindProperty("tcp").objectReferenceValue=cs.FindProperty("tcp").objectReferenceValue;iks.ApplyModifiedPropertiesWithoutUndo();}if(iks.FindProperty("tcp").objectReferenceValue==null)throw new Exception("Front TCP missing");lines.Add("FrontArmIK + CorrectionSequence + TCP: connected");}
 var loaders=all.OfType<BoxAttacher>().ToArray();if(loaders.Length!=3)throw new Exception("Expected 3 suction robots, got "+loaders.Length);
 foreach(var loader in loaders){var so=new SerializedObject(loader);var tote=so.FindProperty("tote").objectReferenceValue as ToteBase;if(tote==null)throw new Exception("Tote missing: "+loader.name);if(loader.tcp==null||loader.suctionCup==null||loader.armIK==null)throw new Exception("Suction references missing");loader.container=tote.transform;loader.slots=(Transform[])tote.slots.Clone();tote.loader=loader;if(loader.slots.Length!=8||loader.slots.Any(x=>x==null||!x.IsChildOf(tote.transform))||loader.slots.Distinct().Count()!=8)throw new Exception("Invalid tote slots");EditorUtility.SetDirty(loader);EditorUtility.SetDirty(tote);lines.Add("Suction robot "+loader.transform.position+" local="+loader.transform.localPosition+" parent="+(loader.transform.parent==null?"ROOT":loader.transform.parent.name)+" parentPos="+(loader.transform.parent==null?Vector3.zero:loader.transform.parent.position)+" parentRot="+(loader.transform.parent==null?Vector3.zero:loader.transform.parent.rotation.eulerAngles)+" scale="+(loader.transform.parent==null?Vector3.one:loader.transform.parent.lossyScale)+": IK/TCP/tote/eight slots OK");}
 var stations=new SerializedObject(cell).FindProperty("terminalStations");if(stations.arraySize!=3)throw new Exception("Three terminal stations required");var stationLoaders=new HashSet<UnityEngine.Object>();for(int i=0;i<3;i++){var station=stations.GetArrayElementAtIndex(i);var l=station.FindPropertyRelative("loader").objectReferenceValue as BoxAttacher;var belt=station.FindPropertyRelative("line").objectReferenceValue as ConveyorLine;if(l==null||belt==null||belt.StopPoint==null)throw new Exception("Terminal handoff missing");if(!stationLoaders.Add(l))throw new Exception("Duplicate terminal robot");float distance=Vector3.Distance(belt.StopPoint.position,l.transform.position);lines.Add("Terminal "+i+": stop to robot distance="+distance.ToString("F3"));if(distance>1.1f)throw new Exception("Terminal robot mismatch: "+i+" stop="+belt.StopPoint.position+" robot="+l.transform.position);}
 foreach(string id in new[]{"A","B","C"}){var cam=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsInactive.Include).Single(c=>c.name=="Camera"+id+"_Arm"&&c.gameObject.scene==scene);if(Vector3.Dot(cam.transform.forward,Vector3.down)<.99f)throw new Exception("Arm camera not downward: "+id);lines.Add("Camera"+id+"_Arm downward at "+cam.transform.position);}
 EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
 File.WriteAllLines("Logs/MergeSceneAudit.txt",new[]{"PASS edit-mode scene connections and C# compilation"}.Concat(lines));EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllLines("Logs/MergeSceneAudit.txt",new[]{"FAIL",e.ToString()}.Concat(lines));Debug.LogException(e);EditorApplication.Exit(1);}}
}